// Pure, deterministic renderer for the generated Chapter 1 voice manifest source.
// No React, no Three.js, no Node API and no audio API.

import type { VoiceClipEntry, VoiceManifest } from "./manifestTypes";

export const MANIFEST_HEADER =
  "// Generated by `scripts/generate-chapter1-voice.mjs`. Do not edit by hand.";

const MANIFEST_EXPORT_NAME = "chapter1VoiceManifest";
const MANIFEST_DECLARATION = `export const ${MANIFEST_EXPORT_NAME}: VoiceManifest = `;

/** Code-point comparison, so the order never depends on the runtime locale. */
function compareText(a: string, b: string): number {
  if (a < b) return -1;
  if (a > b) return 1;
  return 0;
}

function compareEntries(a: VoiceClipEntry, b: VoiceClipEntry): number {
  return compareText(a.clipId, b.clipId) || compareText(a.locale, b.locale);
}

/** Copies an entry with a fixed key order. Optional fields are left out when absent. */
function orderedEntry(entry: VoiceClipEntry): Record<string, unknown> {
  const ordered: Record<string, unknown> = {
    clipId: entry.clipId,
    nodeId: entry.nodeId,
    graphId: entry.graphId,
    speakerId: entry.speakerId,
    locale: entry.locale,
    status: entry.status,
    sources: entry.sources.map((source) => ({ src: source.src, type: source.type })),
  };
  if (entry.durationMs !== undefined) ordered.durationMs = entry.durationMs;
  if (entry.bytes !== undefined) ordered.bytes = entry.bytes;
  ordered.tone = entry.tone;
  ordered.voiceNote = entry.voiceNote;
  ordered.origin = entry.origin;
  ordered.credit = entry.credit;
  ordered.sourceTextHash = entry.sourceTextHash;
  return ordered;
}

/** Produces deterministic TypeScript source for `chapter1.manifest.ts`. */
export function renderManifest(manifest: VoiceManifest): string {
  const clips = [...manifest.clips].sort(compareEntries).map(orderedEntry);
  const literal = {
    schemaVersion: manifest.schemaVersion,
    chapterId: manifest.chapterId,
    clips,
  };
  const body = JSON.stringify(literal, null, 2);
  return [
    MANIFEST_HEADER,
    `import type { VoiceManifest } from "./manifestTypes";`,
    "",
    `${MANIFEST_DECLARATION}${body};`,
    "",
  ].join("\n");
}

/**
 * Reads the manifest back from source made by `renderManifest`.
 * The object literal is JSON, so it is read with `JSON.parse`; nothing is evaluated.
 * Throws when the source does not have the expected shape.
 */
export function parseManifestSource(source: string): VoiceManifest {
  const start = source.indexOf(MANIFEST_DECLARATION);
  if (start < 0) {
    throw new Error("Manifest source: export declaration not found.");
  }
  const end = source.lastIndexOf(";");
  if (end <= start) {
    throw new Error("Manifest source: closing semicolon not found.");
  }
  const literal = source.slice(start + MANIFEST_DECLARATION.length, end);
  return JSON.parse(literal) as VoiceManifest;
}
